package br.radaraero.widget;
import android.app.*;import android.appwidget.*;import android.os.*;import android.content.*;import android.widget.*;import android.text.InputType;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.view.View;import org.json.*;
public class ConfigureActivity extends Activity {
 static final String RADAR="https://riquee05.github.io/radar-aero/radar.html";
 int widgetId; int pinCountBefore=-1; AlertDialog helpDialog; EditText lat,lon,url; Spinner radius,aircraftCount; TextView notice;int ink=Color.rgb(237,245,237),muted=Color.rgb(145,170,156),lime=Color.rgb(177,246,122);
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 GradientDrawable background(int color,int stroke){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(14));if(stroke!=0)d.setStroke(dp(1),stroke);return d;}
 TextView text(LinearLayout box,String value,int size,int color){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(8),0,dp(8));box.addView(t);return t;}
 Button button(LinearLayout box,String value,boolean primary){Button b=new Button(this);b.setText(value);b.setTextSize(13);b.setAllCaps(false);b.setTextColor(primary?Color.rgb(15,35,22):ink);b.setBackground(background(primary?lime:Color.rgb(22,47,32),Color.rgb(51,82,58)));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(50));lp.setMargins(0,dp(10),0,0);box.addView(b,lp);return b;}
 @Override public void onCreate(Bundle b){super.onCreate(b);setResult(RESULT_CANCELED);getWindow().setStatusBarColor(Color.rgb(7,27,24));getWindow().setNavigationBarColor(Color.rgb(7,27,24));widgetId=getIntent().getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,AppWidgetManager.INVALID_APPWIDGET_ID);
 ScrollView scroll=new ScrollView(this);scroll.setBackgroundColor(Color.rgb(7,27,24));LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(22),dp(38),dp(22),dp(36));scroll.addView(box);setContentView(scroll);
 ImageView logo=new ImageView(this);logo.setImageResource(R.drawable.radar_icon);logo.setContentDescription("Radar Aero");box.addView(logo,new LinearLayout.LayoutParams(dp(58),dp(58)));text(box,"RADAR AERO / WIDGET ANDROID · 0.5.0",10,lime);text(box,"Seu radar, na tela inicial.",28,ink);text(box,"Adicione o widget agora. Depois escolha seu ponto em Ajustes, sem rastreamento em segundo plano.",14,muted);
 notice=text(box,"Você pode adicionar o widget antes de configurar as coordenadas.",13,lime);Button pin=button(box,widgetId==AppWidgetManager.INVALID_APPWIDGET_ID?"Adicionar widget à tela inicial":"Adicionar agora e configurar depois",true);pin.setOnClickListener(v->addWidget());Button manual=button(box,"Não abriu? Adicionar pelo menu Widgets",false);manual.setOnClickListener(v->manualHelp());
 Button open=button(box,"Abrir mapa do Radar Aero →",false);open.setOnClickListener(v->openRadar());
 text(box,"O QUE MOSTRAR NO WIDGET",11,lime);aircraftCount=new Spinner(this);aircraftCount.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"1 avião — o mais próximo","Até 3 aviões — conforme tamanho"}));aircraftCount.setSelection(getSharedPreferences("radar",0).getInt("aircraftCount",3)==1?0:1);box.addView(aircraftCount,new LinearLayout.LayoutParams(-1,dp(50)));text(box,"Toque em um voo para abrir a aeronave no mapa. Para ver três aviões, aumente a altura do widget. A escolha vale para todos os seus widgets.",12,muted);Button countSave=button(box,"Aplicar quantidade de aviões",false);countSave.setOnClickListener(v->{getSharedPreferences("radar",0).edit().putInt("aircraftCount",aircraftCount.getSelectedItemPosition()==0?1:3).apply();RadarWidget.drawAll(this,"");feedback("Quantidade aplicada. Não é necessário alterar seu ponto.");});text(box,"SEU PONTO DE REFERÊNCIA",11,lime);lat=field(box,"Latitude (-90 a 90)",true);lon=field(box,"Longitude (-180 a 180)",true);url=field(box,"Endereço HTTPS do radar",false);url.setText(RADAR);
 text(box,"Raio de busca",12,muted);radius=new Spinner(this);radius.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"5 km","10 km","25 km","50 km"}));radius.setSelection(1);box.addView(radius,new LinearLayout.LayoutParams(-1,dp(50)));
 String saved=getSharedPreferences("radar",0).getString("point",null);if(saved!=null)try{fill(new JSONObject(saved));}catch(Exception ignored){}
 Button imp=button(box,"Importar configuração do radar",false);imp.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("application/json");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,7);});
 Button save=button(box,"Salvar ponto e atualizar",true);save.setOnClickListener(v->save());

 text(box,"Todos os widgets compartilham o mesmo ponto. Você pode configurá-lo depois em Ajustes.",12,muted);text(box,"Consulta manual ou automática a cada 30 minutos, sujeita ao Android. O widget mostra o horário da consulta. Distância horizontal e altitude barométrica; não representa altura sobre sua casa. Dados: adsb.lol · ODbL. Não usar para navegação aérea.",11,muted);
 }
 EditText field(LinearLayout box,String hint,boolean number){text(box,hint,12,muted);EditText e=new EditText(this);e.setHint(hint);e.setTextColor(ink);e.setHintTextColor(muted);e.setSingleLine(true);e.setTextSize(14);e.setPadding(dp(14),dp(10),dp(14),dp(10));e.setBackground(background(Color.rgb(15,37,26),Color.rgb(44,72,52)));e.setInputType(number?InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL|InputType.TYPE_NUMBER_FLAG_SIGNED:InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI);box.addView(e,new LinearLayout.LayoutParams(-1,dp(50)));return e;}

 void feedback(String message){if(notice!=null)notice.setText(message);Toast.makeText(this,message,Toast.LENGTH_LONG).show();}
 void finishWidgetSetup(){Intent result=new Intent();result.putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,widgetId);setResult(RESULT_OK,result);RadarWidget.drawAll(this,"");finish();}
 void addWidget(){if(widgetId!=AppWidgetManager.INVALID_APPWIDGET_ID){finishWidgetSetup();return;}AppWidgetManager manager=AppWidgetManager.getInstance(this);try{if(!manager.isRequestPinAppWidgetSupported()){manualHelp();return;}pinCountBefore=manager.getAppWidgetIds(new ComponentName(this,RadarWidget.class)).length;Intent success=new Intent(this,RadarWidget.class).setAction(RadarWidget.PINNED);PendingIntent callback=PendingIntent.getBroadcast(this,4210,success,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);boolean requested=manager.requestPinAppWidget(new ComponentName(this,RadarWidget.class),null,callback);if(!requested){manualHelp();return;}feedback("Solicitação enviada ao Android. Confirme Adicionar. Se nada abrir, use o botão do menu Widgets.");new Handler(Looper.getMainLooper()).postDelayed(()->{if(!isFinishing()&&hasWindowFocus()&&pinCountBefore>=0&&manager.getAppWidgetIds(new ComponentName(this,RadarWidget.class)).length<=pinCountBefore)manualHelp();},2500);}catch(IllegalStateException|SecurityException e){manualHelp();}}
 void manualHelp(){if(isFinishing()||isDestroyed()||helpDialog!=null&&helpDialog.isShowing())return;helpDialog=new AlertDialog.Builder(this).setTitle("Adicionar no Galaxy").setMessage("1. Vá para a tela inicial do celular.\n2. Mantenha pressionado um espaço vazio.\n3. Toque em Widgets.\n4. Procure Radar Aero Widget.\n5. Escolha o widget e toque em Adicionar.\n\nSe abrir esta configuração, toque em Adicionar agora e configurar depois. Não é necessário preencher coordenadas para adicionar.").setPositiveButton("Ir para tela inicial",(d,w)->startActivity(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME))).setNegativeButton("Voltar",null).show();}
 @Override protected void onResume(){super.onResume();if(pinCountBefore>=0){int count=AppWidgetManager.getInstance(this).getAppWidgetIds(new ComponentName(this,RadarWidget.class)).length;if(count>pinCountBefore){pinCountBefore=-1;feedback("Widget adicionado. Use Ajustes no widget para escolher seu ponto.");}}}

 void openRadar(){String link=RADAR;try{String saved=getSharedPreferences("radar",0).getString("point",null);if(saved!=null){String value=new JSONObject(saved).optString("radarUrl",RADAR);if(value.startsWith("https://")&&!value.startsWith("https://radar-aero.e8zxc1.chatgpt.site"))link=value;}}catch(Exception ignored){}startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse(link)));}
 static byte[] readLimited(java.io.InputStream in,int max)throws java.io.IOException{java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] buffer=new byte[4096];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>max)throw new java.io.IOException("Arquivo muito grande");out.write(buffer,0,n);}return out.toByteArray();}
 void fill(JSONObject p)throws Exception{lat.setText(p.getString("lat"));lon.setText(p.getString("lon"));String link=p.optString("radarUrl",RADAR);url.setText(link.isEmpty()||link.startsWith("https://radar-aero.e8zxc1.chatgpt.site")?RADAR:link);int r=p.optInt("radiusKm",10);radius.setSelection(r==5?0:r==25?2:r==50?3:1);}
 void save(){try{double a=Double.parseDouble(lat.getText().toString().trim().replace(',', '.')),o=Double.parseDouble(lon.getText().toString().trim().replace(',', '.'));if(!Double.isFinite(a)||!Double.isFinite(o)||Math.abs(a)>90||Math.abs(o)>180)throw new Exception();String link=url.getText().toString().trim();if(link.isEmpty())link=RADAR;android.net.Uri u=android.net.Uri.parse(link);if(!"https".equals(u.getScheme())||u.getHost()==null||u.getUserInfo()!=null)throw new Exception();JSONObject p=new JSONObject();p.put("version",1);p.put("lat",a);p.put("lon",o);p.put("radiusKm",new int[]{5,10,25,50}[radius.getSelectedItemPosition()]);p.put("radarUrl",link);getSharedPreferences("radar",0).edit().putString("point",p.toString()).remove("snapshot").apply();RadarWidget.drawAll(this,"Consultando…");RefreshJob.schedule(this);if(widgetId!=AppWidgetManager.INVALID_APPWIDGET_ID){Intent result=new Intent();result.putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,widgetId);setResult(RESULT_OK,result);finish();}else feedback("Ponto salvo. Agora toque em Adicionar widget à tela inicial.");}catch(Exception e){feedback("Confira as coordenadas e use um endereço HTTPS válido.");}}
 @Override public void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==7&&result==RESULT_OK&&data!=null)try(java.io.InputStream in=getContentResolver().openInputStream(data.getData())){JSONObject p=new JSONObject(new String(readLimited(in,8192),java.nio.charset.StandardCharsets.UTF_8));if(p.optInt("version")!=1)throw new Exception();fill(p);feedback("Ponto importado. Confira e toque em Salvar.");}catch(Exception e){feedback("Não foi possível importar esse arquivo.");}}
}
